import { ChevronRight } from 'lucide-react';
import clsx from 'clsx';
import './AcidBreadcrumb.css';

export interface BreadcrumbItem {
    label: string;
    href?: string;
    current?: boolean;
}

export interface AcidBreadcrumbProps {
    items: BreadcrumbItem[];
    className?: string;
}

export const AcidBreadcrumb = ({ items, className }: AcidBreadcrumbProps) => {
    return (
        <nav className={clsx('ac-breadcrumb', className)} aria-label="Breadcrumb">
            <ol className="ac-breadcrumb-list">
                {items.map((item, index) => (
                    <li key={index} className="ac-breadcrumb-item">
                        {index > 0 && <ChevronRight className="ac-breadcrumb-separator" size={14} />}
                        <a
                            href={item.href || '#'}
                            className={clsx('ac-breadcrumb-link', item.current && 'ac-breadcrumb-current')}
                            aria-current={item.current ? 'page' : undefined}
                        >
                            {item.label}
                        </a>
                    </li>
                ))}
            </ol>
        </nav>
    );
};

.ac-breadcrumb-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0.5rem;
}

.ac-breadcrumb-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.ac-breadcrumb-separator {
    color: var(--ac-text-muted);
}

.ac-breadcrumb-link {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    color: var(--ac-text-secondary);
    text-decoration: none;
    transition: color 0.2s;
}

.ac-breadcrumb-link:hover {
    color: var(--ac-brand);
}

.ac-breadcrumb-link.ac-breadcrumb-current {
    color: var(--ac-text-primary);
    font-weight: 600;
    pointer-events: none;
}
